// Кейс: .qa/tests/home/HM-07-header-prayer-icon.md.
import { expect } from '@wdio/globals';
import { byText, byTextMatches, tapText } from '../../helpers/ui.ts';
import { shown } from '../_lib/app-0710.ts';
import { goHome } from '../_lib/readiness-1910.ts';
import { homePrayerTitle, saveShot } from '../_lib/app-2110.ts';

const ICON: Record<string, string> = { 'שחרית': 'восход (солнце, стрелка вверх)', 'מנחה': 'закат (солнце, стрелка вниз)', 'ערבית': 'луна' };

describe('21.10 — иконка окна молитвы в шапке (#2be089)', () => {
  afterEach(async () => { await goHome().catch(() => {}); });

  it('HM-07 Шапка главной и «המסע שלי»: окно «HH:MM - HH:MM» с иконкой своей молитвы (מנחה — закат, как в «תפילות אחרונות»); скрины для сверки #2be089 #1108fa0d @time @manual-check @prod-safe', async () => {
    await goHome();
    const prayer = await homePrayerTitle();
    expect(prayer).not.toBeNull();
    await expect(byTextMatches('.*\\d{1,2}:\\d{2} - \\d{1,2}:\\d{2}.*')).toBeExisting({ wait: 15000 });
    const f1 = await saveShot(`HM-07-home-${prayer}.png`);

    await tapText('המסע שלי');
    await (await byText('המסע שלי')).waitForExist({ timeout: 20000 });
    await expect(byTextMatches('.*\\d{1,2}:\\d{2} - \\d{1,2}:\\d{2}.*')).toBeExisting({ wait: 15000 });
    const f2 = await saveShot(`HM-07-journey-${prayer}.png`);

    console.log(`[HM-07] молитва окна: «${prayer}» → ожидаемая иконка: ${ICON[prayer!]}. Сверить вручную: ${f1}, ${f2} ` +
      '(та же иконка, что у этой молитвы в «תפילות אחרונות» / «תזכורות מהירות»; Figma S-01 436:1292).');
    expect(await shown(byText('המסע שלי'))).toBe(true);
  });
});
